# 033 - un tasto abbassa la voce del brano che sta suonando.
#
# La voce sta quasi sempre al centro del mix: abbassando quello che le due
# casse hanno in comune, la voce scende. Subito, mentre il brano va, e si
# torna indietro premendo di nuovo. Non separa niente e non crea nessun file.
#
# Misurato su un brano di prova: voce -53 dB, basso -2,4 dB (resta pieno).
# Il grave non si tocca: sotto i 200 Hz cassa e basso restano dove sono.
#
# SE NON VA BENE: `patch_033 = 0` la spegne su una macchina sola.

CODICE_BASS = 'def set_voce(self, quanto):\n    """quanto: 0 = voce com\'e\', 100 = voce giu\' al massimo."""\n    try:\n        q = max(0, min(100, int(quanto))) / 100.0\n    except Exception:\n        q = 0.0\n    self._voce_giu = q\n    if not self._stream:\n        return False\n    if q <= 0:\n        self._togli_dsp_voce()\n        return True\n    if getattr(self, \'_dsp_voce\', None):\n        return True                  # gia\' agganciato: cambia solo il valore\n    return self._aggancia_dsp_voce()\n\n\ndef _togli_dsp_voce(self):\n    h = getattr(self, \'_dsp_voce\', None)\n    if h and self._stream:\n        try:\n            _lib.bass.BASS_ChannelRemoveDSP(self._stream, h)\n        except Exception:\n            pass\n    self._dsp_voce = None\n\n\ndef _aggancia_dsp_voce(self):\n    import ctypes as _c\n    try:\n        import numpy as _np\n    except Exception:\n        print("⚠️ voce giu\': manca numpy")\n        return False\n\n    b = _lib.bass\n    try:\n        b.BASS_ChannelSetDSP.restype = DWORD\n        b.BASS_ChannelSetDSP.argtypes = [DWORD, _c.c_void_p, _c.c_void_p, ctypes.c_int]\n        b.BASS_ChannelRemoveDSP.argtypes = [DWORD, DWORD]\n    except Exception:\n        pass\n\n    PROC = _c.CFUNCTYPE(None, DWORD, DWORD, _c.c_void_p, DWORD, _c.c_void_p)\n\n    # memoria di lavoro del filtro: serve a ricordare fra un blocco e\n    # l\'altro (il filtro sui bassi ha bisogno del campione precedente)\n    # N = quanti campioni fa la media. 220 a 44.100 = taglio intorno ai\n    # 200 Hz: sotto quella soglia (cassa, basso) non si tocca niente.\n    stato = {\'n\': 220, \'coda\': _np.zeros(219, dtype=_np.float32)}\n\n    def _filtro(handle, canale, buffer, lunghezza, utente):\n        try:\n            q = getattr(self, \'_voce_giu\', 0.0)\n            if q <= 0 or not lunghezza:\n                return\n            n = lunghezza // 4                      # campioni float32\n            if n < 2:\n                return\n            dati = _np.ctypeslib.as_array(\n                _c.cast(buffer, _c.POINTER(_c.c_float)), shape=(n,))\n            if n % 2:\n                return\n            s = dati.reshape(-1, 2)\n            L = s[:, 0].astype(_np.float32, copy=True)\n            R = s[:, 1].astype(_np.float32, copy=True)\n\n            centro = (L + R) * 0.5\n\n            # ⭐ dal centro si tiene fuori il GRAVE: cassa e basso stanno\n            #    li\' e devono restare.\n            #\n            # ⛔ QUI NON CI VA UN CICLO: questa funzione la chiama la\n            #    scheda audio molte volte al secondo, e un ciclo Python\n            #    campione per campione non fa in tempo — il suono\n            #    uscirebbe spezzettato. Media mobile con le somme\n            #    cumulate: stesso effetto, tutto in un colpo solo.\n            N = stato[\'n\']\n            coda = stato[\'coda\']\n            lungo = _np.concatenate((coda, centro))\n            cs = _np.cumsum(lungo, dtype=_np.float64)\n            cs = _np.concatenate(([0.0], cs))\n            inizio = len(coda)\n            grave = ((cs[inizio + 1:] - cs[inizio + 1 - N:len(cs) - N])\n                     / float(N)).astype(_np.float32)\n            # si tiene la coda per il blocco successivo: senza, a ogni\n            # blocco il filtro ripartirebbe e si sentirebbe un tic\n            stato[\'coda\'] = lungo[-(N - 1):] if N > 1 else lungo[:0]\n\n            da_togliere = (centro - grave) * q\n            s[:, 0] = L - da_togliere\n            s[:, 1] = R - da_togliere\n        except Exception:\n            pass                     # il suono non si ferma mai per un errore qui\n\n    self._dsp_voce_proc = PROC(_filtro)      # va TENUTO: se lo raccoglie\n                                             # il garbage collector, crash\n    try:\n        h = b.BASS_ChannelSetDSP(self._stream, self._dsp_voce_proc, None, 0)\n    except Exception as e:\n        print(f"⚠️ voce giu\': {e}")\n        return False\n    if not h:\n        print("⚠️ voce giu\': BASS non ha agganciato il filtro")\n        return False\n    self._dsp_voce = h\n    return True'

CODICE_SYS = 'def _filtro_voce(self, quanto: int):\n    """La riga di filtro da dare a MPV. Vuota = suono naturale.\n\n    ⛔ NON basta abbassare il centro e via: MISURATO, `stereotools` da\n       solo porta giu\' la voce E IL BASSO della stessa quantita\' (-12 dB\n       tutti e due), perche\' anche cassa e basso stanno al centro: il\n       brano si svuota. Percio\' il suono si divide in due strade: sotto i\n       200 Hz non si tocca niente, sopra si abbassa il centro, poi si\n       rimette insieme. Misurato cosi\': voce -24 dB, basso -0,3.\n    """\n    try:\n        q = max(0, min(100, int(quanto)))\n    except Exception:\n        q = 0\n    if q <= 0:\n        return \'\'\n    # 0 = voce com\'e\', 100 = quasi via\n    mlev = max(0.05, 1.0 - (q / 100.0) * 0.95)\n    # quanto porta via il taglio del centro, e quanto va rimesso sui bassi:\n    # il rapporto 0,75 e\' MISURATO (con 1 a 1 il brano veniva gonfio di\n    # bassi: +4 dB invece di 0)\n    import math as _m\n    tolto = -20.0 * _m.log10(mlev)\n    gain = int(round(tolto * 0.75))\n    return ("stereotools=mlev=%.3f,"\n            "bass=frequency=150:width_type=h:width=100:gain=%d"\n            % (mlev, gain))\n\n\ndef set_voce(self, quanto: int):\n    """Abbassa il volume della VOCE del brano che sta suonando.\n\n    quanto: 0 = com\'e\', 100 = voce giu\' al massimo.\n\n    ⛔ NON separa e NON produce nessun file: agisce sul suono mentre\n       esce, come una manopola, e si sente subito. Chi canta dal vivo\n       non puo\' aspettare un minuto per ogni brano.\n    """\n    try:\n        self.voce_giu = max(0, min(100, int(quanto)))\n    except Exception:\n        self.voce_giu = 0\n    fatto = False\n    perche = \'\'\n\n    # ⭐ SUI VIDEO (e sulle basi prese da YouTube) si fa come per la\n    #    TONALITA\': l\'audio si stacca dal video, VLC resta muto e suona\n    #    MPV. A quel punto il filtro lo applica MPV per conto suo, con\n    #    codice suo — niente codice nostro dentro il suono, che e\'\n    #    esattamente cio\' che aveva bloccato il programma.\n    try:\n        if (self.engine.is_video and self.engine.vlc_player\n                and self.mpv_player and not self.is_midi and self.is_playing):\n            if self.voce_giu > 0 and not self._video_pitch_active:\n                self._activate_video_mpv_audio()\n            elif (self.voce_giu == 0 and self._video_pitch_active\n                  and not self.current_pitch):\n                # si torna al video solo se non serve piu\' nemmeno per\n                # la tonalita\'\n                self._deactivate_video_mpv_audio()\n    except Exception as e:\n        print(f"⚠️ audio separato: {e}")\n\n    try:\n        if self.mpv_player is not None and (self.is_mpv_audio\n                                            or self._video_pitch_active):\n            self.mpv_player[\'af\'] = self._filtro_voce(self.voce_giu)\n            fatto = True\n        else:\n            be = self.bass_engine\n            if be is None:\n                perche = \'nessun motore audio buono (ne- MPV ne- BASS)\'\n            elif not getattr(be, \'_stream\', None):\n                perche = \'BASS c-e- ma non ha nessun brano aperto\'\n            else:\n                fatto = bool(be.set_voce(self.voce_giu))\n                if not fatto:\n                    perche = \'BASS non ha agganciato il filtro\'\n    except Exception as e:\n        perche = \'%s: %s\' % (type(e).__name__, e)\n\n    # ⚠️ Si SCRIVE cosa e- successo: senza, premendo il tasto e non\n    #    sentendo niente non c-e- modo di sapere dove si e- fermato.\n    try:\n        import datetime as _dt\n        import os as _os\n        _d = _os.path.join(_os.environ.get(\'LOCALAPPDATA\') or\n                           _os.path.expanduser(\'~\'), \'KaraDom\')\n        _os.makedirs(_d, exist_ok=True)\n        with open(_os.path.join(_d, \'patch033.log\'), \'a\',\n                  encoding=\'utf-8\') as _f:\n            _f.write(\'%s  voce a %d%%: %s%s\\n\' % (\n                _dt.datetime.now().strftime(\'%Y-%m-%d %H:%M:%S\'),\n                self.voce_giu, \'FATTO\' if fatto else \'NON fatto\',\n                \'\' if fatto else \' - \' + perche))\n    except Exception:\n        pass\n\n    if not fatto:\n        print("ℹ️ voce giu\' non applicata: %s" % perche)\n    return fatto\n\n\ndef play(self, tonalita=None):\n    dbg("SYSTEM", f"play() ton={tonalita} is_playing={self.is_playing} is_paused={self.is_paused} gen={self._play_generation}")\n    """\n    Avvia riproduzione — se in pausa, riavvia da 0\n    """\n    # ✅ Sincronizza pitch: se specificato aggiorna, altrimenti mantieni corrente\n    if tonalita is not None:\n        self.current_pitch = tonalita\n\n    # ⭐ La voce abbassata vale anche per il brano che sta per partire:\n    #    la si decide PRIMA di premere play, come la tonalita\', e resta\n    #    finche\' non si rimette su. Si riapplica appena il brano parte,\n    #    perche\' ogni brano nuovo riparte con l\'audio pulito.\n    try:\n        if getattr(self, \'voce_giu\', 0):\n            # ⚠️ `self.master`, non `self.root`: in questa classe `root`\n            #    non esiste e l\'errore sarebbe finito nell\'except — la\n            #    voce non si sarebbe riapplicata mai, senza dire niente.\n            self.master.after(400, lambda q=self.voce_giu: self.set_voce(q))\n    except Exception:\n        pass\n\n    # ✅ Se in PAUSA → riavvia da 0 direttamente su ogni player\n    if self.is_paused:\n        print("▶ Play durante pausa → riavvio diretto da 0")\n        self.is_paused = False\n        self.is_playing = True\n        self._seeking = True\n        self.current_time_ms = 0\n        \n        # Reset monitor\n        self.monitor.current_index = -1\n        self.monitor._current_scroll_line = 0\n        self.monitor._scroll_fraction = 0.0\n        self.monitor._scroll_target_fraction = 0.0\n        self.monitor._cached_scroll_index = -1\n        self.monitor.text_widget.yview_moveto(0)\n        if self.monitor_pubblico:\n            pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n            pub.current_index = -1\n            pub._current_scroll_line = 0\n            pub._scroll_fraction = 0.0\n            pub._scroll_target_fraction = 0.0\n            pub._cached_scroll_index = -1\n            pub.text_widget.yview_moveto(0)\n        \n        # Riavvia audio per tipo di player\n        if self.engine.is_video and self.engine.vlc_player:\n            try:\n                self.engine.vlc_player.set_pause(0)  # Forza unpause\n                self.engine.vlc_player.set_time(0)\n                if self.engine.vlc_player_pubblico:\n                    self.engine.vlc_player_pubblico.set_pause(0)\n                    self.engine.vlc_player_pubblico.set_time(0)\n                if self._video_pitch_active and self.vlc_audio:\n                    self.vlc_audio.set_pause(0)\n                    self.vlc_audio.set_time(0)\n            except Exception as e:\n                print(f"⚠️ Restart video da pausa: {e}")\n        elif self.is_bass_audio and self.bass_engine:\n            try:\n                if self.bass_engine.is_paused:\n                    self.bass_engine.pause()  # toggle → resume\n                self.bass_engine.seek_ms(0)\n                print("▶ Audio BASS riavviato da 0")\n                # ✅ riavvia anche la voce guida in cuffia da 0\n                try:\n                    from .cuffia_guida import guida as _guida\n                    _guida.play(self.current_file, sync_ms=0)\n                except Exception as _e:\n                    print(f"⚠️ voce guida: {_e}")\n            except Exception as e:\n                print(f"⚠️ Restart BASS da pausa: {e}")\n        elif self.is_mpv_audio and self.mpv_player:\n            try:\n                self.mpv_player[\'pause\'] = False\n                self.mpv_player.seek(0, \'absolute\')\n            except Exception as e:\n                print(f"⚠️ Restart MPV da pausa: {e}")\n        elif self.is_vlc_audio and self.vlc_audio:\n            try:\n                self.vlc_audio.set_pause(0)  # Forza unpause (non toggle!)\n                self.vlc_audio.set_time(0)\n                self._vlc_play_start = time.time()\n                self._vlc_last_time = 0\n                self._vlc_last_change = 0\n            except Exception as e:\n                print(f"⚠️ Restart VLC audio da pausa: {e}")\n        elif self.is_midi and self.fs:\n            try:\n                self.fs.pause()  # Riprendi (toggle)\n                self.fs.seek_ms(0)\n                self.seek_offset_ms = 0\n            except Exception as e:\n                print(f"⚠️ Restart MIDI da pausa: {e}")\n        else:\n            try:\n                pygame.mixer.music.play(start=0)\n                self.seek_offset_ms = 0\n            except Exception as e:\n                print(f"⚠️ Restart pygame da pausa: {e}")\n        \n        self.web_sync.send_pause(False)\n        self._start_armed_audio_recording()\n        self.master.after(200, lambda: setattr(self, \'_seeking\', False))\n        print("⏮️ Riavvio da pausa completato")\n        return\n    \n    # ✅ RESET PAUSA\n    self.is_paused = False\n    \n    # ✅ BLOCCA aggiornamenti monitor durante startup (VLC riporta garbage iniziale)\n    self._seeking = True\n    self._play_generation += 1  # ✅ Invalida callback stale dal playback precedente\n    \n    # ✅ RIMUOVO il check is_playing - ora si può premere play anche durante la riproduzione\n    # (gestito in ui.py che chiama stop() prima)\n    \n    if not self.current_file:\n        print("⚠️ Nessun file caricato")\n        return\n    \n    # ✅ Se il file è stato scaricato (dopo stop/fade), ricaricalo\n    if getattr(self, \'_file_unloaded\', False):\n        print("🔄 File scaricato — ricarico prima di play...")\n        self._file_unloaded = False\n        self.load_file(self._original_file or self.current_file, self.current_pitch)\n        # load_file imposta _seeking=True, play() continuerà normalmente\n    \n    # ✅ RICARICA TESTO SOLO SE NECESSARIO (fix play dopo stop senza bloccare UI)\n    # ⛔ Durante pitch swap (_skip_monitor_reset), NON toccare il monitor — è lo stesso file\n    if self.engine.syllables_data and not getattr(self, \'_skip_monitor_reset\', False):\n        # Controlla se il testo è già caricato nel monitor\n        # ✅ Controlla anche se il text_widget è effettivamente vuoto\n        widget_empty = False\n        try:\n            widget_text = self.monitor.text_widget.get(\'1.0\', \'end\').strip()\n            widget_empty = len(widget_text) == 0\n        except:\n            widget_empty = True\n        \n        needs_reload = (not self.monitor.syllables_data or \n                       not self.monitor.full_text or\n                       widget_empty)  # ✅ Forza reload se widget vuoto\n        \n        if needs_reload:\n            print("🔄 Ricarico testo nel monitor...")\n            self.monitor.load_text(\n                self.engine.full_text,\n                self.engine.syllables_data,\n                self.engine,\n                self.current_file\n            )\n            if self.monitor_pubblico:\n                self.monitor_pubblico.monitor_frame.load_text(\n                    self.engine.full_text,\n                    self.engine.syllables_data,\n                    self.engine,\n                    self.current_file if str(self.current_file).lower().startswith(\n                        ("http://", "https://")) else Path(self.current_file).name\n                )\n        else:\n            # ✅ Testo già caricato — reset indice e scroll ISTANTANEO (no lerp)\n            self.monitor.current_index = -1\n            self.monitor._scroll_position = 0.0\n            self.monitor._last_scroll_time = 0\n            self.monitor._cached_scroll_index = -1\n            self.monitor._snap_scroll = True  # ✅ Forza snap, no animazione\n            self.monitor.text_widget.yview_moveto(0)\n            if self.monitor_pubblico:\n                pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n                pub.current_index = -1\n                pub._scroll_position = 0.0\n                pub._last_scroll_time = 0\n                pub._cached_scroll_index = -1\n                pub._snap_scroll = True  # ✅ Forza snap, no animazione\n                pub.text_widget.yview_moveto(0)\n    \n    # ✅ NON chiamare reset() qui - cancella lo sfondo appena caricato!\n    # self.monitor.reset()\n    \n    # ✅ NASCONDI LOGO durante riproduzione (ma NON in sottofondo solo audio)\n    if self.monitor.logo_label and not getattr(self, \'_sottofondo_solo_audio\', False):\n        self.monitor.logo_label.place_forget()\n    \n    # ✅ NASCONDI OVERLAY IMMAGINE durante riproduzione (monitor pubblico)\n    if self.monitor_pubblico and self.monitor_pubblico.image_overlay_enabled:\n        self.monitor_pubblico.hide_image_overlay()\n    \n    if self.engine.is_video:\n        try:\n            # ✅ RIPRISTINA LAYOUT VIDEO (necessario dopo fade_out che smonta il canvas)\n            mon = self.monitor\n            try:\n                mon.text_widget.pack_forget()\n                if hasattr(mon, \'text_frame\') and mon.text_frame:\n                    mon.text_frame.place_forget()\n                if hasattr(mon, \'background_canvas\') and mon.background_canvas:\n                    mon.background_canvas.place_forget()\n                if hasattr(mon, \'logo_label\') and mon.logo_label:\n                    mon.logo_label.place_forget()\n                mon.video_canvas.pack(fill=tk.BOTH, expand=True)\n            except: pass\n            \n            # ✅ Ripristina anche monitor pubblico\n            if self.monitor_pubblico and self.monitor_pubblico.visible:\n                try:\n                    pub = self.monitor_pubblico.monitor_frame\n                    pub.text_widget.pack_forget()\n                    if hasattr(pub, \'text_frame\') and pub.text_frame:\n                        pub.text_frame.place_forget()\n                    if hasattr(pub, \'background_canvas\') and pub.background_canvas:\n                        pub.background_canvas.place_forget()\n                    if hasattr(pub, \'logo_label\') and pub.logo_label:\n                        pub.logo_label.place_forget()\n                    pub.video_canvas.pack(fill=tk.BOTH, expand=True)\n                except: pass\n            \n            # ✅ Re-attach HWND (può perdersi dopo fade_out → stop)\n            try:\n                mon.update_idletasks()\n                v_id = mon.video_canvas.winfo_id()\n                if sys.platform.startswith(\'win\'):\n                    self.engine.vlc_player.set_hwnd(v_id)\n                elif sys.platform.startswith(\'linux\'):\n                    self.engine.vlc_player.set_xwindow(v_id)\n            except: pass\n            \n            self.master.update_idletasks()\n            \n            # ===== PITCH + SPEED VIDEO CON VLC RATE =====\n            pitch_rate = pow(2.0, self.current_pitch / 12.0) if self.current_pitch != 0 else 1.0\n            combined_rate = pitch_rate * self.current_speed\n            self.engine.vlc_player.set_rate(combined_rate)\n            if combined_rate != 1.0:\n                print(f"[VIDEO] 🎵 Rate: {combined_rate:.3f} (pitch={self.current_pitch:+d}, speed={self.current_speed:.2f}x)")\n            # ===== FINE PITCH + SPEED VIDEO =====\n            \n            # ✅ SETUP PLAYER PUBBLICO SE VISIBILE (istanza --no-audio)\n            if self.monitor_pubblico and self.monitor_pubblico.visible:\n                print(f"🎬 Setup player pubblico: file={self.current_file[-50:]}")\n                ok = self.engine.setup_public_video_player(self.monitor_pubblico.monitor_frame, self.current_file)\n                if ok and self.engine.vlc_player_pubblico:\n                    self.engine.vlc_player_pubblico.set_rate(combined_rate)\n                    # Avvia pubblico (già muto per --no-audio)\n                    self.engine.vlc_player_pubblico.play()\n                    time.sleep(0.1)\n                    print("🔇 Player pubblico avviato (--no-audio)")\n                else:\n                    print("⚠️ Player pubblico NON configurato")\n            else:\n                if self.monitor_pubblico:\n                    print(f"🎬 Monitor pubblico non visibile (visible={self.monitor_pubblico.visible})")\n            \n            # PLAY principale\n            self.engine.vlc_player.play()\n            \n            # ✅ RETRY: VLC a volte non parte al primo play() (pipeline codec non pronto)\n            # stream di rete: piu\' tentativi (il CDN puo\' rifiutare la prima\n            # apertura con un 403 transitorio; ri-play() la ritenta)\n            _retry_n = 20 if str(getattr(self, \'current_file\', \'\') or \'\').lower().startswith(\n                (\'http://\', \'https://\')) else 5\n\n            def _verify_vlc_playing(retries=_retry_n):\n                try:\n                    if not self.is_playing or not self.engine.is_video:\n                        return\n                    if not self.engine.vlc_player:\n                        return\n                    if not self.engine.vlc_player.is_playing() and retries > 0:\n                        print(f"⚠️ VLC non partito — retry ({retries} rimasti)")\n                        # ✅ Re-attach HWND prima del retry (a volte si perde)\n                        try:\n                            v_id = self.monitor.video_canvas.winfo_id()\n                            if sys.platform.startswith(\'win\'):\n                                self.engine.vlc_player.set_hwnd(v_id)\n                        except: pass\n                        self.engine.vlc_player.play()\n                        if self.engine.vlc_player_pubblico:\n                            try: self.engine.vlc_player_pubblico.play()\n                            except: pass\n                        self.master.after(500, lambda: _verify_vlc_playing(retries - 1))\n                    elif self.engine.vlc_player.is_playing():\n                        print("✅ VLC video confermato in riproduzione")\n                except:\n                    pass\n            self.master.after(500, _verify_vlc_playing)\n            \n            # ✅ AUDIO DEL VIDEO ESTRATTO SUBITO, in background.\n            # VLC non sa cambiare tonalita\' (ha solo la velocita\'): la\n            # trasposizione vera la fa MPV sull\'audio estratto. Prima\n            # l\'estrazione partiva al PRIMO tocco della tonalita\', e finche\'\n            # non finiva il video suonava alterato nella velocita\'. Ora si\n            # estrae appena parte il brano: quando il cantante chiede il\n            # tono, il motore e\' gia\' pronto.\n            if self.mpv_player and not self.is_midi:\n                self.master.after(800, self._preestrai_audio_video)\n\n            if self.current_pitch != 0 and self.mpv_player:\n                _pitch_for_video = self.current_pitch\n                def _trigger_video_pitch():\n                    if self.is_playing and self.engine.is_video:\n                        self.set_pitch(_pitch_for_video)\n                self.master.after(1500, _trigger_video_pitch)\n            \n            # ✅ SETTA VOLUME SUBITO (con gain normalizzazione — VLC max 100%)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            _norm_vol = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n            self.engine.vlc_player.audio_set_volume(_norm_vol)\n            \n            # ✅ VERIFICA VOLUME DOPO PLAY (backup — VLC a volte ignora volume prima del buffering)\n            def _verify_vlc_volume():\n                try:\n                    is_muted = self.engine.vlc_player.audio_get_mute()\n                    if is_muted:\n                        self.engine.vlc_player.audio_set_mute(False)\n                    \n                    _ng2 = self.normalization_gain if self.normalization_enabled else 1.0\n                    _nv = int(min(100, self._user_volume * max(1.0, _ng2) * 100))\n                    self.engine.vlc_player.audio_set_volume(_nv)\n                    \n                    # Se durata non era disponibile, prova ora\n                    if self.engine.total_duration_ms == 0:\n                        duration_ms = self.engine.vlc_player.get_length()\n                        if duration_ms > 0:\n                            self.engine.total_duration_ms = duration_ms\n                            self.monitor.total_duration_ms = duration_ms\n                            total_min = int(duration_ms / 60000)\n                            total_sec = int((duration_ms % 60000) / 1000)\n                            self.monitor.total_label.config(text=f"{total_min:02d}:{total_sec:02d}")\n                            self.monitor.countdown_label.config(text=f"-{total_min:02d}:{total_sec:02d}")\n                            if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n                                self.info_brano_ref[\'duration\'].config(text=f"{total_min:02d}:{total_sec:02d}")\n                        else:\n                            # Riprova tra 500ms\n                            self.master.after(500, _verify_vlc_volume)\n                except:\n                    pass\n            self.master.after(300, _verify_vlc_volume)\n            \n            print("▶ Video avviato (principale con audio, pubblico muto)")\n            \n            self.start_time = time.time() * 1000\n            self.is_playing = True\n            self._video_play_start = time.time()  # ✅ Grace period per end-detection\n            self._video_has_started = False        # ✅ VLC non ha ancora suonato un frame\n            print(f"▶ Video avviato: {Path(self.current_file).name}")\n            \n            # ✅ Se REC rapido è armato, avvia ora: dopo il play effettivo\n            self._start_armed_audio_recording()\n\n            # ✅ Avvia thread per sync video\n            self.playback_thread = threading.Thread(target=self._playback_loop, daemon=True)\n            self.playback_thread.start()\n            # ✅ SBLOCCA monitor dopo stabilizzazione VLC (solo se non è pitch swap)\n            if not getattr(self, \'_skip_monitor_reset\', False):\n                self.master.after(300, lambda: setattr(self, \'_seeking\', False))\n                # ✅ SAFETY BACKUP\n                self.master.after(1500, lambda: setattr(self, \'_seeking\', False))\n        except Exception as e:\n            print(f"⚠️ Errore play video: {e}")\n            import traceback\n            traceback.print_exc()\n        return\n    \n    self.is_playing = True\n    self.seek_offset_ms = 0  # ✅ Reset offset quando si parte dall\'inizio\n    \n    print(f"[PLAY] is_midi={self.is_midi}, is_vlc_audio={self.is_vlc_audio}, "\n          f"vlc_audio={self.vlc_audio is not None}, is_cdg={self.is_cdg}, "\n          f"file={Path(self.current_file).name if self.current_file else \'None\'}")\n    dbg("SYSTEM", f"PLAY: midi={self.is_midi} vlc={self.is_vlc_audio} cdg={self.is_cdg} file={Path(self.current_file).name if self.current_file else \'None\'}")\n    \n    # ✅ Invia sync web karaocanto.it ad ogni play (non solo al load)\n    try:\n        if self.web_sync.connected and self.current_file:\n            title = getattr(self.engine, \'title\', \'\') or Path(self.current_file).stem\n            artist = getattr(self.engine, \'artist\', \'\')\n            self.web_sync.send_song_start(title, artist, self.engine.syllables_data)\n    except Exception as e:\n        print(f"⚠️ WebSync send_song_start: {e}")\n    \n    try:\n        # ✅ Se è MIDI usa FluidSynth\n        if self.is_midi and self.fs:\n            print(f"🎹 Avvio MIDI con FluidSynth: fs.initialized={self.fs.initialized}")\n            # ✅ APPLICA PITCH PRIMA DI PLAY\n            if self.current_pitch != 0 and hasattr(self.fs, \'set_pitch\'):\n                try:\n                    self.fs.set_pitch(self.current_pitch)\n                    print(f"🎵 MIDI pitch pre-play: {self.current_pitch:+d}")\n                except:\n                    pass\n            self.fs.play()\n            self._midi_play_start = time.time()  # ✅ Grace period per end-detection\n            # ✅ RIAPPLICA PITCH DOPO PLAY (safety: fs.play() chiama stop() interno\n            #    che potrebbe interferire con il valore impostato)\n            if self.current_pitch != 0 and hasattr(self.fs, \'set_pitch\'):\n                try:\n                    self.fs.set_pitch(self.current_pitch)\n                    print(f"🎵 MIDI pitch post-play: {self.current_pitch:+d}")\n                except:\n                    pass\n            self.start_time = time.time() * 1000\n            print(f"▶ MIDI avviato con FluidSynth: {Path(self.current_file).name}")\n        elif self.is_midi and not self.fs:\n            print("❌ MIDI ma FluidSynth non disponibile!")\n            return\n        elif self.is_bass_audio and self.bass_engine:\n            # ✅ BASS Engine audio (48kHz/32bit) — solo pitch, no speed\n            _be = self.bass_engine\n            # Applica pitch (senza toccare velocità)\n            if self.current_pitch != 0:\n                _be.set_pitch(self.current_pitch)\n            # Applica volume (con gain normalizzazione real-time — max 100%)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            _bass_vol = min(1.0, self._user_volume * max(1.0, _ng))\n            _be.set_master_gain(_bass_vol)\n            if _ng > 1.05:\n                print(f"🔊 BASS volume: {_bass_vol:.2f} (user={self._user_volume:.0%} × gain={_ng:.2f})")\n            # End callback\n            _be.on_playback_end = lambda: self.master.after(0, self._on_bass_audio_end)\n            _be.play()\n            self.start_time = time.time() * 1000\n            print(f"▶ Audio BASS avviato: {Path(self.current_file).name}")\n            # ✅ Avvia la voce guida in cuffia per QUALSIASI percorso di play\n            #    (libreria, comandi in basso, playlist anche automatiche)\n            try:\n                from .cuffia_guida import guida as _guida\n                _pos = 0\n                try: _pos = self.bass_engine.get_position_ms()\n                except Exception: _pos = 0\n                _guida.play(self.current_file, sync_ms=_pos)\n            except Exception as _e:\n                print(f"⚠️ voce guida: {_e}")\n        elif self.is_mpv_audio and self.mpv_player:\n            # ✅ MPV audio\n            pending = getattr(self, \'_mpv_pending_file\', self.current_file)\n            self.mpv_player.play(pending.replace(\'\\\\\', \'/\'))\n            self.start_time = time.time() * 1000\n            self._mpv_started_pos = None\n            \n            # ✅ SEMPRE applica rate/pitch — pulisce rubberband residuo\n            self._apply_rate()\n            \n            # Volume — imposta subito E verifica dopo\n            self._apply_mpv_volume()\n            \n            print(f"▶ Audio MPV avviato: {Path(pending).name}")\n\n            # Watchdog: alcuni file KFN/MKF possono restare fermi a 0s pur risultando "idle"\n            def _mpv_start_watchdog(expected_file=pending):\n                try:\n                    if not (self.is_mpv_audio and self.mpv_player):\n                        return\n                    pos = self.mpv_player.time_pos\n                    eof = bool(getattr(self.mpv_player, \'eof_reached\', False))\n                    if pos is not None and pos > 0.35:\n                        self._mpv_started_pos = pos\n                        return\n                    if eof:\n                        return\n                    if (getattr(self, \'is_kfn\', False) or getattr(self, \'is_mkf\', False)) and int(getattr(self, \'current_pitch\', 0) or 0) == 0:\n                        try:\n                            pygame.mixer.music.load(expected_file)\n                            self.mpv_player.command(\'stop\')\n                            self.is_mpv_audio = False\n                            print(f"⚠️ MPV fermo a 0s su {Path(expected_file).name} → fallback pygame")\n                        except Exception as pe:\n                            print(f"⚠️ MPV fermo a 0s ma fallback pygame fallito: {pe}")\n                except Exception:\n                    pass\n            self.master.after(2200, _mpv_start_watchdog)\n            \n            # Durata e verifica volume (dopo 500ms per dare tempo a MPV)\n            def _mpv_setup():\n                try:\n                    if self.mpv_player and self.is_mpv_audio:\n                        # ✅ VERIFICA VOLUME (con gain normalizzazione)\n                        try:\n                            actual_vol = self.mpv_player.volume\n                            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                            expected_vol = min(100, self._user_volume * max(1.0, _ng) * 100)\n                            if actual_vol is not None and abs(actual_vol - expected_vol) > 5:\n                                print(f"⚠️ MPV volume drift: actual={actual_vol:.0f} expected={expected_vol:.0f} → correggo")\n                                self.mpv_player[\'volume\'] = expected_vol\n                            else:\n                                print(f"🔊 MPV volume OK: {actual_vol:.0f}%")\n                        except Exception as ve:\n                            print(f"⚠️ MPV volume check: {ve}")\n                        \n                        dur = self.mpv_player.duration\n                        if dur and dur > 0:\n                            dur_ms = int(dur * 1000)\n                            self.engine.total_duration_ms = dur_ms\n                            self.monitor.total_duration_ms = dur_ms\n                            d_min = int(dur_ms / 60000)\n                            d_sec = int((dur_ms % 60000) / 1000)\n                            self.monitor.total_label.config(text=f"{d_min:02d}:{d_sec:02d}")\n                            self.monitor.countdown_label.config(text=f"-{d_min:02d}:{d_sec:02d}")\n                            if self.monitor_pubblico:\n                                try:\n                                    pub = self.monitor_pubblico.monitor_frame\n                                    pub.total_duration_ms = dur_ms\n                                    pub.total_label.config(text=f"{d_min:02d}:{d_sec:02d}")\n                                    pub.countdown_label.config(text=f"-{d_min:02d}:{d_sec:02d}")\n                                except: pass\n                except: pass\n            self.master.after(500, _mpv_setup)\n            # ✅ Seconda verifica volume a 1500ms (MPV potrebbe resettare dopo buffering)\n            self.master.after(1500, self._apply_mpv_volume)\n        elif self.is_vlc_audio and self.vlc_audio:\n            # ✅ VLC audio-only (qualità professionale)\n            ret = self.vlc_audio.play()\n            dbg("SYSTEM", f"VLC audio play() -> ret={ret}")\n            if ret == -1:\n                print("⚠️ VLC play() → -1, fallback pygame")\n                self.is_vlc_audio = False\n                # ✅ CLEANUP VLC prima del fallback (rilascia file lock)\n                try:\n                    self.vlc_audio.stop()\n                    self.vlc_audio.set_media(None)\n                except:\n                    pass\n                self.vlc_audio = None\n                self._seeking = True  # ✅ Previeni false detection "finito"\n                try:\n                    pygame.mixer.music.load(self.current_file)\n                    pygame.mixer.music.play()\n                    dbg("SYSTEM", "pygame music.play()")\n                    pygame.mixer.music.set_volume(self._user_volume)\n                    print("✅ Fallback pygame riuscito (play -1)")\n                except Exception as pe:\n                    print(f"❌ Anche pygame fallito: {pe}")\n                self.master.after(500, lambda: setattr(self, \'_seeking\', False))\n            else:\n                self._vlc_play_start = time.time()  # ✅ Grace period per is_playing()\n                # ✅ SETTA VOLUME SUBITO (con gain normalizzazione — VLC max 100%)\n                _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                vol_pct = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n                self.vlc_audio.audio_set_volume(vol_pct)\n                # ✅ APPLICA PITCH+SPEED SUBITO (rispetta Pedalboard)\n                if self.current_pitch != 0 or self.current_speed != 1.0:\n                    if getattr(self, \'_pitched_file\', None):\n                        # Pitch è nel file → solo speed\n                        self.vlc_audio.set_rate(max(0.25, min(4.0, self.current_speed)))\n                        print(f"🎵 VLC audio: speed={self.current_speed:.2f}x (pitch nel file Pedalboard)")\n                    else:\n                        # Fallback: pitch+speed combinati\n                        _rate = pow(2.0, self.current_pitch / 12.0) * self.current_speed\n                        self.vlc_audio.set_rate(_rate)\n                        print(f"🎵 VLC audio rate={_rate:.3f} (pitch={self.current_pitch:+d}, speed={self.current_speed:.2f}x)")\n            \n            self.start_time = time.time() * 1000\n            \n            # ✅ Volume e durata DOPO che VLC è partito (non subito)\n            def _vlc_audio_setup():\n                try:\n                    if not self.is_vlc_audio or not self.vlc_audio:\n                        return\n                    # ✅ SAFETY: verifica che VLC stia effettivamente suonando\n                    if not self.vlc_audio.is_playing():\n                        print("⚠️ VLC audio non partito dopo 500ms, fallback pygame")\n                        self.is_vlc_audio = False\n                        # ✅ CLEANUP VLC prima del fallback\n                        try:\n                            self.vlc_audio.stop()\n                            self.vlc_audio.set_media(None)\n                        except:\n                            pass\n                        self.vlc_audio = None\n                        # ✅ Previeni false detection "finito" durante switch\n                        self._seeking = True\n                        try:\n                            pygame.mixer.music.load(self.current_file)\n                            pygame.mixer.music.play()\n                            pygame.mixer.music.set_volume(self._user_volume)\n                            self.start_time = time.time() * 1000\n                            print("✅ Fallback pygame riuscito")\n                        except Exception as pe:\n                            print(f"❌ Anche pygame fallito: {pe}")\n                        # ✅ Rilascia flag dopo breve delay\n                        self.master.after(500, lambda: setattr(self, \'_seeking\', False))\n                        return\n                    # Volume (con gain normalizzazione — VLC max 100%)\n                    _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                    vol_pct = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n                    self.vlc_audio.audio_set_volume(vol_pct)\n                    print(f"🔊 VLC audio: volume={vol_pct}%, is_playing=True")\n                    # Durata\n                    dur = self.vlc_audio.get_length()\n                    if dur > 0:\n                        self.engine.total_duration_ms = dur\n                        if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n                            dur_min = int(dur / 60000)\n                            dur_sec = int((dur % 60000) / 1000)\n                            self.info_brano_ref[\'duration\'].config(text=f"{dur_min:02d}:{dur_sec:02d}")\n                    else:\n                        # Riprova durata tra 500ms\n                        def _retry_dur():\n                            try:\n                                if self.is_vlc_audio and self.vlc_audio:\n                                    d = self.vlc_audio.get_length()\n                                    if d > 0:\n                                        self.engine.total_duration_ms = d\n                            except:\n                                pass\n                        self.master.after(500, _retry_dur)\n                except Exception as e:\n                    print(f"⚠️ VLC audio setup: {e}")\n            self.master.after(500, _vlc_audio_setup)  # ✅ 500ms per dare tempo a VLC\n            print(f"▶ Audio VLC avviato: {Path(self.current_file).name}")\n        else:\n            # ✅ RICARICA FILE AUDIO SE È STATO SCARICATO DA STOP()\n            try:\n                pygame.mixer.music.play()\n            except:\n                # File scaricato, ricarica\n                print("🔄 Ricarico file audio...")\n                pygame.mixer.music.load(self.current_file)\n                pygame.mixer.music.play()\n            \n            self.start_time = time.time() * 1000\n            print(f"▶ Audio avviato: {Path(self.current_file).name}")\n            \n            # ✅ Applica volume (pygame capped a 1.0 — gain normalizzazione non supportato)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            pygame.mixer.music.set_volume(max(0.0, min(1.0, self._user_volume * max(1.0, _ng))))\n        \n        # ✅ Aggiorna duration label nei controlli in basso\n        if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n            total_ms = 0\n            if self.engine and self.engine.total_duration_ms > 0:\n                total_ms = self.engine.total_duration_ms\n            elif self.monitor.syllables_data:\n                total_ms = self.monitor.syllables_data[-1][1]\n            \n            if total_ms > 0:\n                total_sec = int(total_ms / 1000)\n                self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n    except Exception as e:\n        print(f"⚠️ Errore play audio: {e}")\n        self.is_playing = False\n        return\n    \n    # ✅ Se REC rapido è armato, avvia ora: dopo il play effettivo\n    self._start_armed_audio_recording()\n\n    self.playback_thread = threading.Thread(target=self._playback_loop, daemon=True)\n    self.playback_thread.start()\n    \n    # ✅ Applica pitch+speed salvati SOLO se diversi da default\n    if self.current_pitch != 0 or self.current_speed != 1.0:\n        self.master.after(400, self._apply_rate)\n    \n    # ✅ SBLOCCA monitor dopo che VLC/pygame si è stabilizzato (solo se non è pitch swap)\n    if not getattr(self, \'_skip_monitor_reset\', False):\n        self.master.after(300, lambda: setattr(self, \'_seeking\', False))\n        # ✅ SAFETY BACKUP: se il primo after non parte (mainloop occupato), rilascia comunque\n        self.master.after(1500, lambda: setattr(self, \'_seeking\', False))'

CODICE_YT = 'def _on_devocalizza(self):\n    """Abbassa il volume della voce del brano che sta suonando.\n\n    ⛔ NON separa e NON produce nessun file: il suono viene lavorato\n       mentre esce, come si abbassa un volume. Effetto immediato, e si\n       torna indietro premendo di nuovo.\n    """\n    giu = not getattr(self, \'_voce_giu_attiva\', False)\n    livello = 0\n    if giu:\n        # quanto abbassarla: la scelta sta nelle Opzioni (scheda Audio)\n        try:\n            livello = int(str(Database.get_config(\'voce_giu\', \'85\')).strip())\n        except Exception:\n            livello = 85\n        livello = max(1, min(100, livello))\n    try:\n        self.system.set_voce(livello)\n    except Exception as e:\n        print("[voce] %s" % e)\n    self._voce_giu_attiva = giu\n    self._aggiorna_btn_devoc()\n\n\ndef _aggiorna_btn_devoc(self):\n    b = getattr(self, \'btn_devoc\', None)\n    if b is None:\n        return\n    try:\n        if getattr(self, \'_voce_giu_attiva\', False):\n            b.config(text=_("rimetti\\nla voce"), bg=\'#d35400\', fg=\'white\')\n        else:\n            b.config(text=_("abbassa\\nla voce"), bg=\'#8e44ad\', fg=\'white\')\n    except Exception:\n        pass\n\n\ndef _leggi_filtro_karaoke(self):\n    """Acceso, se non e\' stato spento apposta. La scelta si ricorda: chi\n    cerca gli originali non deve rispegnerlo a ogni avvio."""\n    try:\n        from .database import Database\n        return str(Database.get_config(\'yt_filtro_karaoke\', \'1\')).strip() not in (\'0\', \'no\', \'off\')\n    except Exception:\n        return True\n\n\ndef _aggiorna_btn_karaoke(self):\n    """Acceso = verde. Spento = grigio e barrato, cosi\' si capisce a colpo\n    d\'occhio che quella parola NON viene aggiunta."""\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return\n    # ⚠️ NON si usa `BTN`: quello e\' una variabile locale di __init__ e qui\n    #    dentro non esiste. Il font si richiede a F, che e\' importata dal\n    #    modulo e tiene conto del ridimensionamento dello schermo.\n    #\n    # Il testo dice cosa succede PREMENDOLO, non com\'e\' adesso: e\' l\'unico\n    # modo perche\' si capisca senza doverci pensare.\n    try:\n        if self._filtro_karaoke:\n            b.config(text=_("togli filtro\\nkaraoke"),\n                     bg=\'#28a745\', fg=\'white\', font=F(\'Segoe UI\', 9, \'bold\'))\n        else:\n            b.config(text=_("rimetti filtro\\nkaraoke"),\n                     bg=\'#495057\', fg=\'#ffd700\', font=F(\'Segoe UI\', 9, \'bold\'))\n    except Exception:\n        pass\n\n# ---------------- togliere la voce ----------------\n\n\ndef _cambia_filtro_karaoke(self):\n    self._filtro_karaoke = not self._filtro_karaoke\n    self._aggiorna_btn_karaoke()\n    try:\n        from .database import Database\n        Database.set_config(\'yt_filtro_karaoke\', \'1\' if self._filtro_karaoke else \'0\')\n    except Exception:\n        pass\n\n\ndef _largh_btn_karaoke(self):\n    """Quanto e\' largo il tasto del filtro con la scritta piu\' lunga.\n\n    Si misura senza toccare quella che si vede: si mette da parte il testo\n    attuale, si provano tutte e due le scritte, e si rimette com\'era.\n    """\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return 0\n    try:\n        adesso = b.cget(\'text\')\n        largo = 0\n        for t in (_("togli filtro\\nkaraoke"), _("rimetti filtro\\nkaraoke")):\n            b.config(text=t)\n            b.update_idletasks()\n            largo = max(largo, b.winfo_reqwidth())\n        b.config(text=adesso)\n        return largo\n    except Exception:\n        return 0\n\n\ndef _layout_top(self):\n    top = getattr(self, \'_top\', None)\n    if top is None or not top.winfo_exists():\n        return\n    # ⛔ QUI SI CREANO TUTTI E DUE I BOTTONI: questa funzione ne posiziona\n    #    due, e le patch si sostituiscono a vicenda — chi arriva per ultimo\n    #    deve bastare a se stesso, o l\'altro bottone resta inesistente\n    #    (\'NoneType\' has no attribute \'place\', con l\'errore in faccia).\n    if getattr(self, \'btn_karaoke\', None) is None:\n        self._filtro_karaoke = self._leggi_filtro_karaoke()\n        self.btn_karaoke = tk.Button(top, text=_("togli filtro\\nkaraoke"),\n                                     command=self._cambia_filtro_karaoke,\n                                     relief=\'flat\', cursor=\'hand2\',\n                                     bd=0, highlightthickness=0)\n        self._aggiorna_btn_karaoke()\n    if getattr(self, \'btn_devoc\', None) is None:\n        self.btn_devoc = tk.Button(top, text=_("abbassa\\nla voce"),\n                                   command=self._on_devocalizza,\n                                   bg=\'#8e44ad\', fg=\'white\',\n                                   relief=\'flat\', cursor=\'hand2\')\n        self._aggiorna_btn_devoc()\n        try:\n            from .libreria_widgets import add_tooltip as _tt\n            _tt(self.btn_devoc,\n                _("Abbassa la voce del brano che sta suonando, subito. "\n                  "Premi di nuovo per rimetterla."))\n        except Exception:\n            pass\n    try:\n        top.update_idletasks()\n    except Exception:\n        pass\n    W = top.winfo_width()\n    H = top.winfo_height()\n    if W < 40 or H < 10:\n        return\n    ox = top.winfo_rootx()\n\n    def rel(w):\n        try:\n            if w is None:\n                return None\n            wd = w.winfo_width()\n            if wd < 5:\n                return None\n            return (w.winfo_rootx() - ox, wd)\n        except Exception:\n            return None\n\n    lib = getattr(self.system, \'libreria\', None)\n    cant = rel(getattr(lib, \'entry_cantante\', None))\n    brano = rel(getattr(lib, \'_lbl_brano\', None))\n    filt = rel(getattr(lib, \'entry_filtro\', None))\n    pad = S(4)\n\n    # --- Dest: label allineata a "Cant:", campo allineato/largo come cantante ---\n    if cant:\n        xcant, wcant = cant\n    else:\n        xcant, wcant = S(60), (W // 2) - S(90)\n    # X della label "Cant:" = inizio del frame cantante + padx(5)\n    lbl_x = S(5)\n    try:\n        fc = self.system.libreria.entry_cantante.master\n        lbl_x = (fc.winfo_rootx() - ox) + S(5)\n    except Exception:\n        pass\n    self.lbl_dest.place(x=max(0, lbl_x), y=0, height=H)\n    self.entry_dest.place(x=xcant, y=0, width=wcant, height=H)\n\n    # --- Sfoglia sotto i tasti ▶ 🗑 (tra campo cantante e label brano) ---\n    gap_x0 = xcant + wcant + pad\n    gap_x1 = (brano[0] if brano else (filt[0] if filt else W)) - pad\n    sfw = max(S(70), gap_x1 - gap_x0)\n    self.btn_sfoglia.place(x=gap_x0, y=0, width=sfw, height=H)\n\n    # --- campo ricerca: dalla label "Brano (filtro):" a fine campo filtro ---\n    if brano:\n        xsearch = brano[0]\n    elif filt:\n        xsearch = filt[0]\n    else:\n        xsearch = gap_x0 + sfw + pad\n    filtro_right = (filt[0] + filt[1]) if filt else W\n\n    # --- 3 bottoni (Cerca/Download/Incolla) TUTTI larghi uguali (al piu\' largo) ---\n    # ⚠️ La larghezza si prende sul testo PIU\' LUNGO che ciascun bottone\n    #    puo\' mostrare, non su quello di adesso: il tasto del filtro\n    #    cambia scritta quando lo si preme, e se la misura seguisse il\n    #    testo corrente la barra si riassesterebbe a ogni clic.\n    bw = max(self.btn_cerca.winfo_reqwidth(),\n             self.btn_download.winfo_reqwidth(),\n             self.btn_incolla.winfo_reqwidth(),\n             self.btn_devoc.winfo_reqwidth(),\n             self._largh_btn_karaoke()) + S(4)   # appena un filo d\'aria\n    buttons_w = 4 * bw + 4 * pad     # Cerca, Download, Incolla, Devocalizza\n    search_right = min(filtro_right, W - buttons_w - pad)\n    search_right = max(search_right, xsearch + S(80))\n\n    # ⭐ L\'interruttore "karaoke" sta IN FONDO al campo, dentro il suo\n    #    spazio: il campo si accorcia di quel tanto. Cosi\' si vede mentre\n    #    si scrive, senza rubare posto ai tre bottoni.\n    campo_right = max(xsearch + S(60), search_right - bw - pad)\n    self.entry_search.place(x=xsearch, y=0, width=campo_right - xsearch, height=H)\n    self.btn_karaoke.place(x=campo_right + pad, y=0,\n                           width=search_right - campo_right - pad, height=H)\n\n    bx = search_right + pad\n    self.btn_cerca.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_download.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_incolla.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_devoc.place(x=bx, y=0, width=bw, height=H)\n\n# ---------------- scroll rotellina ----------------'


def _spenta():
    try:
        from moduli.database import Database
        if str(Database.get_config('patch_033', '1')).strip() in ('0', 'no', 'off'):
            traccia('spenta a mano (patch_033 = 0)')
            return True
    except Exception:
        pass
    return False


def traccia(testo):
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch033.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                testo) + chr(10))
    except Exception:
        pass


def apply():
    if _spenta():
        traccia('non mi accendo (vedi la riga qui sopra)')
        return False
    fatte = []
    try:
        # 1) il filtro nel motore audio
        import moduli.bass_engine as mb
        sp = mb.__dict__
        exec(compile(CODICE_BASS, "<patch033bass>", "exec"), sp)
        for n in ('set_voce', '_togli_dsp_voce', '_aggancia_dsp_voce'):
            setattr(mb.BassEngine, n, sp[n])
        mb.BassEngine._dsp_voce = None
        mb.BassEngine._voce_giu = 0.0
        fatte.append('motore audio')
    except Exception as e:
        traccia('motore audio NON agganciato: %s: %s' % (type(e).__name__, e))
        return False

    try:
        # 2) il comando nel programma
        import moduli.system as ms
        sp = ms.__dict__
        exec(compile(CODICE_SYS, "<patch033sys>", "exec"), sp)
        for n in ('_filtro_voce', 'set_voce', 'play'):
            setattr(ms.KaraokeMonitorSystem, n, sp[n])
        fatte.append('comando')
    except Exception as e:
        traccia('comando NON agganciato: %s: %s' % (type(e).__name__, e))

    try:
        # 3) il tasto
        import moduli.yt2mp3 as my
        C = my.YoutubePanel
        sp = my.__dict__
        exec(compile(CODICE_YT, "<patch033yt>", "exec"), sp)
        for n in ('_on_devocalizza', '_aggiorna_btn_devoc',
                  '_leggi_filtro_karaoke', '_aggiorna_btn_karaoke',
                  '_cambia_filtro_karaoke', '_largh_btn_karaoke',
                  '_layout_top'):
            setattr(C, n, sp[n])
        C.btn_devoc = None
        if getattr(C, 'btn_karaoke', None) is None:
            C.btn_karaoke = None
        fatte.append('tasto')
    except Exception as e:
        traccia('tasto NON agganciato: %s: %s' % (type(e).__name__, e))

    traccia('AGGANCIATA: ' + ', '.join(fatte))
    print("patch 033: si puo' abbassare la voce mentre suona")
    return True


def revert():
    try:
        import sys
        mb = sys.modules.get('moduli.bass_engine')
        if mb and hasattr(mb, 'BassEngine'):
            for n in ('set_voce', '_togli_dsp_voce', '_aggancia_dsp_voce'):
                if hasattr(mb.BassEngine, n):
                    delattr(mb.BassEngine, n)
        print("patch 033: tolta")
        return True
    except Exception as e:
        print("patch 033: %s" % e)
    return False


try:
    apply()
except Exception:
    pass
